package io.knowledgebrain.collaboration;
import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class GroupParticipationTest {
 GroupStore store=mock(GroupStore.class);GroupSpaceClient space=mock(GroupSpaceClient.class);GroupParticipationController api=new GroupParticipationController(store,space);UuidV7 ids=new UuidV7(Clock.systemUTC());UUID group=ids.next(),spaceId=ids.next(),actor=ids.next();String parent="00-"+"a".repeat(32)+"-"+"b".repeat(16)+"-01",token="c".repeat(43);
 MockHttpServletRequest request(){var r=new MockHttpServletRequest("GET","/api/groups/participating");r.setSecure(true);r.addHeader("Cookie","__Host-brain_guest="+token);r.addHeader("traceparent",parent);return r;}
 GroupStore.Group g(){return new GroupStore.Group(group,ids.next(),"Shared config","literal","ACTIVE",spaceId,2,Instant.now(),Instant.now(),"PRIVATE");}
 @Test void memberAndViewerReadAuthorizedActiveConfiguration()throws Exception{for(String role:List.of("MEMBER","VIEWER")){when(space.participation(token,List.of(group),parent)).thenReturn(new GroupSpaceClient.Access(actor,"REGISTERED",List.of(new GroupSpaceClient.Grant(group,spaceId,role,"PRIVATE"))));when(store.active(List.of(group))).thenReturn(List.of(g()));var result=api.detail(group.toString(),request()).getBody();assertEquals(role,result.role());assertEquals(group,result.group().groupId());}verify(space,times(2)).participation(token,List.of(group),parent);}
 @Test void missingOrMismatchingSpaceNeverExposesConfiguration()throws Exception{when(space.participation(token,List.of(group),parent)).thenReturn(new GroupSpaceClient.Access(actor,"REGISTERED",List.of(new GroupSpaceClient.Grant(group,ids.next(),"MEMBER","PRIVATE"))));when(store.active(List.of(group))).thenReturn(List.of(g()));assertThrows(ResponseStatusException.class,()->api.detail(group.toString(),request()));}
 @Test void pendingConfigurationIsFilteredWhileSpaceCursorAdvances()throws Exception{when(space.participations(token,null,20,parent)).thenReturn(new GroupSpaceClient.Participations(actor,"REGISTERED",List.of(new GroupSpaceClient.Grant(group,spaceId,"MEMBER","PRIVATE")),group));when(store.active(List.of(group))).thenReturn(List.of());var p=api.list(request()).getBody();assertTrue(p.items().isEmpty());assertEquals(group,p.nextAfter());}
 @Test void duplicateCookiesUnknownQueryAndBodiesAreRejected(){var duplicate=request();duplicate.addHeader("Cookie","__Host-brain_guest="+token);assertThrows(ResponseStatusException.class,()->api.list(duplicate));var query=request();query.addParameter("ownerId",actor.toString());assertThrows(ResponseStatusException.class,()->api.list(query));var body=request();body.setContent("{}".getBytes());assertThrows(ResponseStatusException.class,()->api.list(body));verifyNoInteractions(space,store);}
}
